sharedState.example:
feature economy version "1.0.0"
command economy permission "aetherscript.example.economy" sender player {
  arg action: text = "show"
  let owner = player_key()
  let balance_key = owner + "_balance"
  let owned_key = owner + "_owned"
  let stock = shared_read("server", "stock", 1)
  let balance = shared_read("server", balance_key, 10)
  let owned = shared_read("server", owned_key, 0)
  if action == "buy" {
    if stock < 1 {
      send "Sold out."
    } else {
      if balance < 5 {
        send "Insufficient balance."
      } else {
        let writes = put(put({"stock": stock - 1}, balance_key, balance - 5), owned_key, owned + 1)
        if shared_commit("server", writes, list<text>()) {
          send "Purchase committed."
        } else {
          send "Purchase conflict; try again."
        }
      }
    }
  } else {
    send "Stock: " + text(stock)
    send "Balance: " + text(balance)
    send "Owned: " + text(owned)
  }
}

menusAndCustomItems.example:
feature menu-shop version "1.0.0"
command menushop permission "aetherscript.example.menushop" sender player {
  let reward = custom_item("cloud_token", "minecraft:paper", "Cloud token", 1)
  let choice = menu_choose("Cloud shop: token costs 1 emerald", [reward])
  if choice == 0 {
    if inventory_exchange(item("minecraft:emerald", 1), reward) {
      send "Purchased one Cloud token."
    } else {
      send "You need one plain emerald and space for a Cloud token."
    }
  } else {
    send "Shop closed."
  }
}

entitiesCombatAndRegions.exampleSource:
feature two-arenas version "1.0.0"
command arenas permission "aetherscript.example.arenas" sender player {
  arg arena: text = "red"
  arg action: text = "show"
  if arena == "red" || arena == "blue" {
    let position = player_location()
    let inside = inside_region(position, 0, -64, 0, 15, 320, 15)
    let in_blue = inside_region(position, 32, -64, 0, 47, 320, 15)
    let allowed = (arena == "red" && inside) || (arena == "blue" && in_blue)
    let score_key = arena + "_score"
    let boss_key = arena + "_boss"
    let score = shared_read("world", score_key, 0)
    let boss = shared_read("world", boss_key, "")
    if action == "target" && team_is(arena) && allowed && boss != "" {
      if entity_target_player(boss) {
        send "Boss targeted " + arena
      }
    }
    if action == "join" {
      team_join(arena)
      send "Joined " + arena
    } else {
      if action == "start" {
        if team_is(arena) && allowed {
          let created = entity_spawn(position, "zombie", arena + " arena boss")
          entity_health(created, 20)
          if shared_commit("world", put(map<text,text>(), boss_key, created), list<text>()) {
            if boss != "" {
              let removed = entity_remove(boss)
            }
            send "Started " + arena + " boss " + created
          } else {
            let removed = entity_remove(created)
            send "Start conflict; retry."
          }
        } else {
          send "Join this team and stand inside its arena first."
        }
      } else {
        if action == "score" {
          if team_is(arena) && allowed {
            if shared_commit("world", put(map<text,integer>(), score_key, score + 1), list<text>()) {
              send arena + " score " + text(score + 1)
            } else {
              send "Score conflict; retry."
            }
          } else {
            send "Join this team and stand inside its arena first."
          }
        } else {
          if action == "cleanup" {
            if shared_commit("world", map<text,text>(), [boss_key]) {
              if boss != "" {
                let removed = entity_remove(boss)
              }
              team_leave()
              send "Cleaned " + arena
            } else {
              send "Cleanup conflict; retry."
            }
          } else {
            send arena + " score " + text(score)
            send "Boss: " + boss
            send "Member: " + text(team_is(arena))
            send "Inside: " + text(allowed)
          }
        }
      }
    }
  } else {
    send "Choose red or blue."
  }
}
on entity_damage permission "aetherscript.example.arenas" {
  if world == "minecraft:overworld" && x >= 0 && x <= 15 && z >= 0 && z <= 15 {
    send "Damage blocked in red."
    cancel
  } else {
    send "Damage: " + entity_type + " " + text(damage_milli)
  }
}
on entity_death permission "aetherscript.example.arenas" {
  send "Death: " + entity_type + " " + entity_uuid
}

externalIntegrations.example:
feature guarded-shop version "1.0.0"
command guardedshop permission "aetherscript.example.guardedshop" sender player {
  arg action: text = "quote"
  let vault_ready = integration_available("vault", "1.7")
  let permissions_ready = integration_available("permissions", "1")
  let regions_ready = integration_available("worldguard", "7.0")
  if vault_ready && permissions_ready && regions_ready {
    if external_permission("aetherscript.shop.buy") {
      if external_can_build(player_location()) {
        let price = 250
        let balance = external_balance()
        if action == "buy" {
          if balance >= price {
            if external_withdraw(price) {
              if inventory_give(item("minecraft:bread", 4)) {
                send "Purchased 4 bread for 250 minor units."
              } else {
                if external_deposit(price) {
                  send "Delivery failed; 250 minor units refunded."
                } else {
                  send "Delivery and refund failed; contact the server owner."
                }
              }
            } else {
              send "Payment rejected; no bread delivered."
            }
          } else {
            send "Insufficient balance; no payment attempted."
          }
        } else {
          send "Quote: 4 bread costs 250 minor units (2.50 major units)."
          send "Balance in minor units: " + text(balance)
        }
      } else {
        send "Shop requires WorldGuard build access here."
      }
    } else {
      send "Missing aetherscript.shop.buy permission."
    }
  } else {
    send "Required providers unavailable or incompatible."
    send "Vault >= 1.7: " + text(vault_ready)
    send "Permissions >= 1: " + text(permissions_ready)
    send "WorldGuard >= 7.0: " + text(regions_ready)
  }
}
